-- stg_mc_strains: part 1 of 1, 102 rows. NOT APPLIED, branch only.
-- Licence on every row comes from the FILE, never the filename.
create table if not exists public.stg_mc_strains (
  strain text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  file_window text,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mc_strains enable row level security;
drop policy if exists stg_mc_strains_read on public.stg_mc_strains;
create policy stg_mc_strains_read on public.stg_mc_strains for select to authenticated using (true);
